package com.creatorhub.servlet; import com.creatorhub.dao.CreatorDAO; import com.creatorhub.util.PasswordUtil; import com.creatorhub.model.Student; import javax.servlet.annotation.WebServlet; import javax.servlet.http.*; import java.io.*; @WebServlet("/login") public class LoginServlet extends HttpServlet{protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{try{Student x=new CreatorDAO().login(r.getParameter("email"),PasswordUtil.sha256(r.getParameter("password")));if(x==null){s.sendRedirect(r.getContextPath()+"/?error=Invalid+email+or+password");return;}HttpSession h=r.getSession();h.setAttribute("studentId",x.getStudentId());h.setAttribute("studentName",x.getName());s.sendRedirect(r.getContextPath()+"/home");}catch(Exception e){throw new IOException(e);}}}
